SELECT t.TASK_ID AS task_id,t.PIPELINE_ID AS pipeline_id,p.PROJECT_ID AS project_id,p.PIPELINE_CODE AS pipeline_code,t.TASK_CODE AS task_code,v.PARAMETER_VALUE AS channel_name,t.CREATE_DATE AS task_created,(SELECT MAX(s.UPDATED_DATE) FROM CFG_TASK_PARAMETERS s WHERE s.TASK_ID=t.TASK_ID AND s.PARAMETER_NAME IN ('ALERT_CHANNEL','ALERT_ON')) AS subscription_changed,c.UPDATED_DATE AS channel_changed FROM CFG_TASKS t JOIN CFG_PIPELINES p ON p.PIPELINE_ID=t.PIPELINE_ID JOIN CFG_TASK_PARAMETERS v ON v.TASK_ID=t.TASK_ID AND v.PARAMETER_NAME='ALERT_CHANNEL' AND v.ACTIVE_FLAG='Y' LEFT JOIN CFG_ALERT_CHANNELS c ON c.PROJECT_ID=p.PROJECT_ID AND c.CHANNEL_NAME=v.PARAMETER_VALUE WHERE t.HANDLER='ALERT' AND t.ACTIVE_FLAG='Y' AND p.ACTIVE_FLAG='Y' ORDER BY t.TASK_ID
